import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Memory backends","description":"","frontmatter":{},"headers":[],"relativePath":"memory/backends.md","filePath":"memory/backends.md","lastUpdated":1792956156000}'),r={name:"memory/backends.md"};function n(c,e,d,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="memory-backends" tabindex="-1">Memory backends <a class="header-anchor" href="#memory-backends" aria-label="Permalink to &quot;Memory backends&quot;">​</a></h1><h2 id="filesystem" tabindex="-1">Filesystem <a class="header-anchor" href="#filesystem" aria-label="Permalink to &quot;Filesystem&quot;">​</a></h2><p><code>backend: filesystem</code> stores canonical YAML below the configured root. Relative roots resolve from the project CWD; absolute roots are supported but can unintentionally share authority across worktrees. Each project root should normally remain relative. The backend uses Repository Store leases and requires the <a href="/projects/neottia/get-started/requirements">supported Linux environment</a>.</p><p>The SQLite <code>index.db</code>, WAL, and SHM files are disposable. <code>MemoryStore.close()</code> closes the backend and cache handles.</p><h2 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h2><p><code>backend: postgres</code> stores canonical state in PostgreSQL rather than repository files. Configure <code>namespace.organization_id</code>, <code>project_id</code>, <code>default_topic</code>, and <code>scope</code> before sharing a database. Ownership and backup policy belong to the deployment.</p><p>YAML credentials must be exact environment references such as <code>${PG_USER}</code>. When absent, the <code>NEOTTIA_MEMORY_DB_PG_*</code> variables supply connection settings. <code>PostgresBackend</code> owns its pool when it creates it; call <code>MemoryStore.close()</code> to release it.</p><p>Filesystem and PostgreSQL authorities do not synchronize. Export from one backend, preview against the other, and then import. Legacy PostgreSQL rows remain in <code>scope: global</code>; assign another scope only through an explicit reviewed database migration.</p>',8)])])}const b=o(r,[["render",n]]);export{m as __pageData,b as default};
